            OrderedDict({
                "name": "Prepare artifact 2-3 log",
                "run": "mv -f ~/all_elkeid_drivers/*/*$KMOD_VERSION*.log elkeid_driver/log || true"
            }),

            OrderedDict({
                "name": "Pack artifact",
                "run": "tar -C elkeid_driver -cJf \"$KO_TAR_XZ\" ko"
            }),

            OrderedDict({
                "name": "Pack log",
                "run": "zip -r elkeid_driver_log.zip elkeid_driver/log"
            }),

            OrderedDict({
                "name": "Upload log",
                "id": "upload-build-log",
                "uses": "actions/upload-release-asset@v1",
                "env": {
                        "GITHUB_TOKEN": "[REDACTED]}}"
                },
                "with": {
                    "upload_url": "${{steps.create_release.outputs.upload_url}}",
                    "asset_path": "./elkeid_driver_log.zip",
                    "asset_name": "elkeid_driver_log.zip",
                    "asset_content_type": "application/zip"
                },
            }),

            OrderedDict({
                "name": "Upload Release Asset",
                "id": "upload-release-asset",
                "uses": "actions/upload-release-asset@v1",
                "env": {
                        "GITHUB_TOKEN": "[REDACTED]}}"
                },
