                    "upload_url": "${{steps.create_release.outputs.upload_url}}",
                    "asset_path": "${{env.KO_TAR_XZ}}",
                    "asset_name": "${{env.KO_TAR_XZ}}",
                    "asset_content_type": "application/x-tar"
                },
            })
