    rm -rf ${root_dir}/plugin
    rm -f /bin/${agent_ctl} /usr/bin/${agent_ctl} /usr/local/bin/${agent_ctl}
}
uninstall() {
	disable_service
    stop_agent
    delete_cgroups
    clean_dirs
}
if [ "$1" == 'remove' ] || [ $1 -eq 0 ]; then
    uninstall
fi

